-- ============================================
-- LUMA — Thème 13 : MOYEN 2/3 x4 — Participer à un panel de questions-réponses
-- ============================================


update scenarios set content = '{"characters": {"moderator": "le modérateur", "panelist": "l''intervenant du panel", "audience": "le public", "audience_member": "un membre du public"}, "start_node": "n1", "nodes": {"n1": {"speaker": "moderator", "text": "We have time for audience participation now — anyone want to share their own experience with this topic?", "text_fr": "On a du temps pour la participation du public maintenant — quelqu''un veut partager sa propre expérience sur ce sujet ?", "choices": [{"text": "(Raise your hand, feeling a mix of nerves and excitement.)", "text_fr": "(Lève la main, ressentant un mélange de nervosité et d''excitation.)", "next": "n2"}, {"text": "(Hesitate, unsure if your experience is relevant enough to share.)", "text_fr": "(Hésite, pas sûr que ton expérience soit assez pertinente à partager.)", "next": "n2b"}]}, "n2": {"speaker": "moderator", "text": "Yes, go ahead! Please share whenever you''re ready.", "text_fr": "Oui, allez-y ! Partagez quand vous êtes prêt.", "choices": [{"text": "Thank you. I actually faced a similar challenge in my own career transition.", "text_fr": "Merci. J''ai en fait fait face à un défi similaire dans ma propre transition de carrière.", "next": "n3"}]}, "n2b": {"speaker": "panelist", "text": "(Notices your hesitation) I saw your hand — please, we''d love to hear your perspective.", "text_fr": "(Remarque ton hésitation) J''ai vu votre main — s''il vous plaît, on aimerait entendre votre perspective.", "choices": [{"text": "Thank you, that''s encouraging. I did face something similar in my career.", "text_fr": "Merci, c''est encourageant. J''ai fait face à quelque chose de similaire dans ma carrière.", "next": "n3"}]}, "n3": {"speaker": "audience", "text": "(All eyes turn toward you, waiting attentively for your story.)", "text_fr": "(Tous les regards se tournent vers vous, attendant attentivement votre histoire.)", "choices": [{"text": "(Share your experience clearly and confidently, despite the nerves.)", "text_fr": "(Partage ton expérience clairement et avec assurance, malgré la nervosité.)", "next": "n4"}]}, "n4": {"speaker": "panelist", "text": "That''s such a valuable perspective, thank you for sharing something so personal.", "text_fr": "C''est une perspective tellement précieuse, merci d''avoir partagé quelque chose d''aussi personnel.", "choices": [{"text": "Of course, I think it''s important these conversations feel real, not just theoretical.", "text_fr": "Bien sûr, je pense que c''est important que ces conversations semblent réelles, pas juste théoriques.", "next": "n5"}]}, "n5": {"speaker": "moderator", "text": "Absolutely agree. Did you find a resolution to that challenge eventually?", "text_fr": "Absolument d''accord. Vous avez fini par trouver une résolution à ce défi ?", "choices": [{"text": "Eventually, yes — though it took longer than I initially expected.", "text_fr": "Finalement, oui — même si ça a pris plus longtemps que prévu initialement.", "next": "n6"}, {"text": "Honestly, I''m still working through it, but I''ve made real progress.", "text_fr": "Honnêtement, je suis encore en train de le résoudre, mais j''ai fait de vrais progrès.", "next": "n6"}]}, "n6": {"speaker": "panelist", "text": "That honesty is refreshing — not everything gets neatly resolved on a set timeline.", "text_fr": "Cette honnêteté est rafraîchissante — tout ne se résout pas proprement selon un calendrier fixe.", "choices": [{"text": "Exactly, and I think acknowledging that helps others feel less alone in their struggles.", "text_fr": "Exactement, et je pense que reconnaître ça aide les autres à se sentir moins seuls dans leurs difficultés.", "next": "n7"}]}, "n7": {"speaker": "audience_member", "text": "(Whispers to a neighbor) That was really relatable, I''m glad they shared that.", "text_fr": "(Chuchote à un voisin) C''était vraiment touchant, je suis content qu''ils aient partagé ça.", "choices": [{"text": "(Feel a small sense of accomplishment, having contributed meaningfully to the discussion.)", "text_fr": "(Ressens un petit sentiment d''accomplissement, ayant contribué de façon significative à la discussion.)", "next": "n8"}]}, "n8": {"speaker": "moderator", "text": "Thank you again for such a genuine contribution to today''s panel discussion.", "text_fr": "Merci encore pour une contribution si sincère à la discussion de panel d''aujourd''hui.", "choices": [{"text": "Thank you for creating a space where sharing like that felt welcomed.", "text_fr": "Merci d''avoir créé un espace où partager comme ça se sentait bienvenu.", "next": "end_shared"}]}, "end_shared": {"speaker": "panelist", "text": "That''s exactly what these panels should be — real conversations, not just polished answers.", "text_fr": "C''est exactement ce que ces panels devraient être — de vraies conversations, pas juste des réponses polies.", "end": true, "ending_label": "Expérience partagée avec sincérité au panel 🎙️💬"}}}'::jsonb, is_playable = true
where title = 'Participer à un panel de questions-réponses'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
